-- Full Control: libera o recurso 'full_control' (aprovado pelo Edimilson em 2026-11-02). Aditivo.
alter table public.recursos_liberados drop constraint recursos_liberados_recurso_check;
alter table public.recursos_liberados add constraint recursos_liberados_recurso_check check (recurso = any (array['buscar'::text, 'assessor_telegram'::text, 'assessor_email'::text, 'whatsapp'::text, 'full_control'::text]));

create or replace function public.meus_recursos() returns text[] language sql stable security definer set search_path to 'public', 'auth' as $function$ select coalesce(array_agg(r), '{}') from unnest(array['buscar','assessor_telegram','assessor_email','whatsapp','full_control']) r where public.tem_recurso(auth.uid(), r) $function$;

create or replace function public.master_definir_liberacao(p_user uuid, p_recurso text, p_ativo boolean) returns void language plpgsql security definer set search_path to 'public', 'auth' as $function$ begin if not public.eh_master() then raise exception 'Acesso restrito ao usuário master'; end if; if p_recurso not in ('buscar','assessor_telegram','assessor_email','whatsapp','full_control') then raise exception 'Recurso inválido'; end if; if p_ativo then insert into public.recursos_liberados (user_id, recurso, liberado_por) values (p_user, p_recurso, auth.uid()) on conflict do nothing; return; end if; perform public.remover_liberacao(p_user, p_recurso); if p_recurso = 'assessor_telegram' then perform public.limpar_telegram_usuario(p_user); elsif p_recurso = 'assessor_email' then perform public.limpar_email_usuario(p_user); elsif p_recurso = 'whatsapp' then perform public.whatsapp_cancelar_usuario(p_user); elsif p_recurso = 'full_control' then perform casa.cancelar_pendentes(p_user); end if; end $function$;
